with valid as (select id, customer_id, plan, start_date, end_date, status, round(monthly_fee, 0) as monthly_fee_rounded from subscriptions where plan != 'premium') select id, plan, monthly_fee_rounded, sum(monthly_fee_rounded) over (partition by customer_id order by monthly_fee_rounded, id rows between unbounded preceding and current row) as running_monthly_fee_rounded, avg(monthly_fee_rounded) over (partition by customer_id, plan order by monthly_fee_rounded, id rows between 6 preceding and 1 preceding) as monthly_fee_rounded_avg_6_prior from valid where monthly_fee_rounded between 40 and 75
